INSERT INTO video_impl_claims VALUES(1,'NPJTYeyCCuY','role',166,NULL,'fb_falseback',NULL,NULL,NULL,'「Marc Pubill como líbero」(마르크 푸빌이 리베로로)','HELD','이미 일치 — squad_entries 푸빌 = fb_falseback/Defend fit .811. 영상이 독립 수렴한 것이라 처방 변경 없음. 재판정 조건: ATM 백3(3-4-2-1) 슬롯 체계가 잠정(LOW-MEDIUM)에서 확정되면 fb_falseback이 백3 리베로 기하와 맞는지 재산출.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(2,'NPJTYeyCCuY','role',160,NULL,'wm_wideplm',NULL,NULL,NULL,'「Álex Baena es el teórico delantero centro, pero su posición media no es la de delantero, sino que es la de centrocampista, media punta」(바에나는 이론상 9번인데 평균 위치는 9번이 아니라 미드필더·메디아푼타다)','HELD','명목 ST ↔ 실측 불일치를 영상이 같은 방향으로 확인했다 — 우리 squad_entries는 이미 slot_type=WM, wm_wideplm/Attack fit .825로 ST가 아니다. 처방 변경 없음. 재판정 조건: ATM 3-4-2-1 슬롯 확정 후 CAM/WM 중 어느 슬롯 기하에 앉는지 재산출.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(3,'NPJTYeyCCuY','limit',NULL,NULL,NULL,NULL,'in_possession','국면별 9번 교대 — 무공 국면에서는 바에나가 9번, 볼 회복 시 줄리아노 시메오네가 9번이 된다','「por qué Álex Baena ahora es el delantero centro cuando el Atlético no tiene el balón. Pero además… por qué se convierte el mismo delantero centro Giuliano Simeone cuando este sí recupera el balón」(공이 없을 때는 바에나가 9번인데, 공을 회복하면 줄리아노 시메오네가 그 9번이 되는 이유)','PENDING','⭐ HANDOFF 미해결 1(ATM 포메이션 표기 충돌)에 직접 대응하는 외부 단서. FC26은 국면별 포지션 교대를 갖지 않으므로 reproduction_limits 후보(기존 formation 축 「국면별 포메이션 전환」과 같은 부류, 단 이건 선수 단위 교대다). 등록 전 2소스 교차검증 필요 — 현재 단일 소스.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(4,'qkcMoU2khyk','limit',NULL,NULL,NULL,NULL,'pressing','trampa pentagonal(오각형 함정) — 라비아·리스 제임스가 밑변, 좌 로저스·우 파머, 꼭대기 주앙 페드루','「la trampa pentagonal, el sistema defensivo que hizo que marcase el primer gol en solamente 30 segundos… Lavia y Rhys James serían la base en el pentágono… por izquierda Rogers, por derecha Palmer y arriba João Pedro」(오각형 함정, 30초 만에 선제골을 만든 수비 시스템 — 라비아와 리스 제임스가 오각형의 밑변, 좌측 로저스, 우측 파머, 꼭대기 주앙 페드루)','PENDING','압박 「형태」에 기하를 부여한 유일한 자료. FC26 팀 설정에 압박 트리거·형태 축이 없어(reproduction_limits pressing 3행) 설정값으로 옮길 수 없다 — reproduction_limits에 「압박 형태(오각 함정)」를 4번째 pressing 행으로 추가할지 판단 필요.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(5,'qkcMoU2khyk','team_axis',NULL,'CHE',NULL,NULL,'formation','3-4-2-1','「vuelve a ese sistema 3-4-2-1 que tantos éxitos le dio en el Leverkusen」(레버쿠젠에서 큰 성공을 준 3-4-2-1로 돌아간다)','HELD','이미 일치 — team_tactic_setups regime 2 projected = 3-4-2-1. 영상은 그 계보(레버쿠젠 → 첼시)를 확인한 것이라 설정 변경 없음. 재판정 조건: 인게임 포메이션은 슬롯 제약으로 5-4-1을 채택 중이므로(reference 행) FC27에서 3-4-2-1 와이드가 FB 슬롯을 받으면 재매핑.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(6,'gVmb3JTFcKU','team_axis',NULL,'CHE',NULL,NULL,'build_up_style','Counter','「What Chelsea are actually doing is inviting the pass wide, then springing the trap… Win it back deep and hit the space they''ve left behind」(첼시가 실제로 하는 것은 측면으로 패스를 유도한 뒤 함정을 작동시키는 것 — 깊은 곳에서 되찾아 상대가 비운 배후 공간을 친다) / 「Chelsea completed just 146 passes all match, their lowest in a Premier League game since 2003-04, and had only 25.6% of the ball, the lowest share on record」(첼시는 경기 내내 146회 패스로 2003-04 이후 프리미어리그 최저, 점유율 25.6%로 기록상 최저였다)','PENDING','⭐⭐ 팀 설정 3축의 실측 침묵 구간(docs/30 7단계 — 전술 분석 1차 소스). 현행 regime 2 projected = Short Passing인데 146패스·점유 25.6%·「유도 후 역습」 구조는 Counter를 지지한다. ⛔ 단 이건 브라이턴전 1경기 표본이고 match_game_setups에 이미 경기 전용으로 반영된 값이므로, 시즌 정본 변경은 2경기 이상 반복 확인 후. 반박권 확인 완료: 실측 점유·패스량이 Counter와 모순되지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(7,'gVmb3JTFcKU','team_axis',NULL,'CHE',NULL,NULL,'defensive_approach','Balanced','「In preseason, we saw an aggressive front-foot Chelsea press going after the opposition''s back line… Since the season started, that press has looked completely different」(프리시즌엔 상대 백라인을 쫓는 적극적 전방 압박이었는데, 시즌이 시작되자 완전히 달라 보인다) / 「Rogers와 주앙 페드루는 중앙에 콤팩트하게 머물며 중앙을 막고 나가지 않는다」','HELD','이미 일치 — regime 2 projected = Balanced(전방 압박 아님). 영상의 「프리시즌 High → 시즌 중 콤팩트」 관측이 우리 Balanced 값을 지지한다. 재판정 조건: reference 행(알론소 블루프린트)은 da=High/line=64를 갖고 있어 두 행이 갈린다 — 공식전 3경기 이상 쌓이면 어느 쪽이 정본인지 확정.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(8,'4kSO-K0pP7U','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Short Passing','「백4가 깊게 서고 중앙 미드 2명이 그 앞으로 내려와 패스 옵션을 준다 · 파우 토레스를 통해 짧은 그라운드 패스로 전진」','REJECTED','⛔ 불변규칙 7 — 2025-12-15 게시·15경기 시점의 **25/26 자료**다(GK 마르티네스, 빌드업 하강 자원 로저스, 추가 옵션 오나나 — 셋 다 26/27 체제에 없다). 26/27 팀 설정 근거로 쓰지 않는다. 취한 것은 「윙어가 접히고 풀백이 폭을 담당」 구조 문법의 외부 확인뿐이고, 그건 docs/20 ⑨로 이미 정본화되어 있어 새 주장이 아니다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(9,'HtPgFuvPe6Q','role',10,NULL,'wm_winger','Attack',NULL,NULL,'「he was playing the game quite high and wide as well... like a traditional winger」(그는 경기를 꽤 높고 넓게, 전통적인 윙어처럼 했다)','REJECTED','⛔ **REJECTED — 반박권 행사**(docs/30 7단계 ⑷). 2026-09-15 규약 적용 결과, 시즌 정본 교정이 **나오지 않는다.** ⑴ **근거 표본을 구분해야 한다** — 시즌 전체 map25(x=85)에서는 `wm_wideplm/Attack` .7614가 1위이고 Δ.0205 ≤ .05로 **실측 무결정**이다(상위 6개가 .7614~.7223 = 폭 .039로 전부 노이즈 밴드 안이며 현행 `wm_widemid/Support`도 5위 .7275로 그 안에 있다). `wm_winger/Attack`은 시즌 기준 **6위 .7223**이다. Δ.0618로 단독 확정이 나온 것은 **최근 6경기·515분 표본**(#418)이고, 시즌 정본의 근거 표본이 아니다(마첸 SEASON-REVISED 선례 — best-game 표본은 공격 출전을 과대가중한다). ⑵ **무결정 구간의 tie-break를 영상에 넘겨도 winger/Attack은 못 된다** — C1(두 줄 4)이 뱅크 질량으로 막는다. obs#39 뱅크 사다리(x=85): widemid/Defend·Balanced 1.30 > **widemid/Support 0.60** > winger/Balanced 0.30 > wideplm·insidefwd·**winger/Attack 0.00**. 좌측 해방(가르나초 뱅크 0.00)이므로 전방 4인의 뱅크는 **RM 한 칸이 전량 부담**한다 — winger/Attack은 그 값을 0으로 만들어 C1을 깬다. 중간안 `wm_winger/Balanced`(뱅크 0.30)도 **obs#125가 이미 판정**했다: 「수비 목적이면 Balanced가 맞지만 그것으로 두 줄 4는 성립하지 않는다」. ⑶ **현행 값은 낡은 argmax가 아니라 「구조 지불」이다** — 원문: 「맥긴의 군 최적은 wm_wideplm/Attack .761이지만 그 조합의 뱅크가 0.00이라 C1이 깨진다 → wm_widemid/Support .728로 **.033을 구조에 지불**했다」. ⑷ ⭐⭐ **결정타 — 이 변수는 이미 인게임 A/B로 측정됐다.** T1↔T2(2026-09-08)가 `RM 맥긴 wideplm/Attack → widemid/Support` **단일 변수** 실험이었고 결과는 맥긴 자기진영 **5.9% → 38.9%**, 「정본 커널(widemid/Support)이 게임 커널보다 실측에 더 가까웠다」(obs#537). 즉 **재현 검증 축(실측 단독 확정)이 영상 주장과 반대 방향으로 이미 닫혀 있다.** ⑸ **영상 주장은 이미 제자리에 반영돼 있다** — 이건 경기 단위 관찰이고 `match_player_prescriptions` report 39는 **이미 `wm_winger/Attack` .767**이다(report 31·1도 동일). 시즌 정본과 경기 전용을 섞지 않는 규약(G12)이 정확히 작동한 사례다. ⇒ **재판정 조건**: ⓐ 좌측 해방을 끄거나 LM이 뱅크를 분담하게 되면(가르나초 뱅크 0.00 → 0.30+) RM의 뱅크 독점이 풀려 재계산 대상 ⓑ 시즌 표본이 쌓여 winger/Attack이 시즌 기준 상위로 올라오고 Δ>.05가 되면 ⓒ T7 A/B에서 widemid/Support의 게임 내 우위가 뒤집히면. ⚠️ obs#764의 이 행 사유(「T7 이월 때문에 HELD」)는 **불완전했다** — 진짜 차단 요인은 C1 뱅크 + obs#537 인게임 A/B다. obs#765가 정정.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
